#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>

#include "defines.hpp"
#include "symm.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// C: i x j
	DEFINE_PROTO_STRUCT(c_layout, j_vec ^ i_vec);
	// A: i x k (square M x M)
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);
	// B: i x j
	DEFINE_PROTO_STRUCT(b_layout, j_vec ^ i_vec);
} tuning;


// initialization function
void init_array(num_t &alpha, num_t &beta, auto C, auto A, auto B) {
	using namespace noarr;

	alpha = (num_t)1.5;
	beta = (num_t)1.2;

	// Initialize C and B:
	//   C[i][j] = ((i + j) % 100) / m
	//   B[i][j] = ((n + i - j) % 100) / m
	traverser(C, B).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		auto m_len = C | get_length<'i'>();
		auto n_len = C | get_length<'j'>();

		C[state] = (num_t)((i + j) % 100) / (num_t)m_len;
		B[state] = (num_t)((n_len + i - j) % 100) / (num_t)m_len;
	});

	// Initialize symmetric matrix A:
	// lower triangle (including diagonal) gets values,
	// strictly upper triangle gets sentinel -999
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		auto m_len = A | get_length<'i'>();

		if (k <= i)
			A[state] = (num_t)((i + k) % 100) / (num_t)m_len;
		else
			A[state] = (num_t)-999;
	});
}


// computation kernel
// Original semantics:
// for (i = 0; i < M; i++)
//   for (j = 0; j < N; j++) {
//     temp2 = 0;
//     for (k = 0; k < i; k++) {
//       C[k][j] += alpha * B[i][j] * A[i][k];
//       temp2 += B[k][j] * A[i][k];
//     }
//     C[i][j] = beta * C[i][j] + alpha * B[i][j] * A[i][i] + alpha * temp2;
//   }
[[gnu::flatten, gnu::noinline]]
void kernel_symm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// C: i x j
	// A: i x k (symmetric, lower triangle used)
	// B: i x j

	#pragma scop
	traverser(C, A, B).template for_dims<'i'>([=](auto trav_i) {
		// Outer loop over rows i
		trav_i.template for_dims<'j'>([=](auto trav_ij) {
			// Middle loop over columns j (for fixed i)
			num_t temp2 = 0;

			// State for (i, j)
			auto state_ij = trav_ij.state();

			// B[i][j] is invariant in the inner k-loop
			num_t Bij = B[state_ij];

			// Inner loop over k
			trav_ij.template for_each<'k'>([&](auto state) {
				// state has indices (i, j, k)
				auto i_idx = get_index<'i'>(state);
				auto k_idx = get_index<'k'>(state);

				if (k_idx < i_idx) {
					// A[i][k]; A has dimensions 'i' and 'k'
					num_t Aik = A[state];

					// Build a state with row index replaced by k:
					// this addresses C[k][j] and B[k][j]
					auto state_kj = state.template with<index_in<'i'>>(k_idx);

					// C[k][j] += alpha * B[i][j] * A[i][k];
					C[state_kj] += alpha * Bij * Aik;

					// temp2 += B[k][j] * A[i][k];
					temp2 += B[state_kj] * Aik;
				}
			});

			// Final update for C[i][j]:
			// C[i][j] = beta * C[i][j]
			//           + alpha * B[i][j] * A[i][i]
			//           + alpha * temp2;
			auto i_idx = get_index<'i'>(state_ij);
			auto state_ii = state_ij.template with<index_in<'k'>>(i_idx);

			C[state_ij] =
				beta * C[state_ij]
				+ alpha * Bij * A[state_ii]
				+ alpha * temp2;
		});
	});
	#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// scalars
	num_t alpha;
	num_t beta;

	// set lengths for all logical dimensions
	auto set_lengths =
		noarr::set_length<'i'>(m)
		^ noarr::set_length<'j'>(n)
		^ noarr::set_length<'k'>(m);

	// data structures
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths);
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize data
	init_array(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_symm(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, C.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}

#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "symm.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// C: i x j
	DEFINE_PROTO_STRUCT(c_layout, j_vec ^ i_vec);
	// A: i x k (square matrix M x M)
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);
	// B: i x j
	DEFINE_PROTO_STRUCT(b_layout, j_vec ^ i_vec);
} tuning;

// initialization function
void init_array(num_t &alpha, num_t &beta, auto C, auto A, auto B) {
	using namespace noarr;

	alpha = (num_t)1.5;
	beta = (num_t)1.2;

	// lengths (m = number of rows, n = number of columns)
	auto m_len = C | get_length<'i'>();
	auto n_len = C | get_length<'j'>();

	// Initialize C and B: full M x N
	traverser(C, B).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		C[state] = (num_t)((i + j) % 100) / (num_t)m_len;
		B[state] = (num_t)((n_len + i - j) % 100) / (num_t)m_len;
	});

	// Initialize A: lower triangular (i >= k), rest set to -999
	auto m_len_a = A | get_length<'i'>();

	traverser(A).template for_dims<'i'>([=](auto trav_i) {
		auto state_i = trav_i.state();
		auto i_idx = get_index<'i'>(state_i);

		trav_i.template for_each<'k'>([=](auto state) {
			auto k_idx = get_index<'k'>(state);

			if (k_idx <= i_idx)
				A[state] = (num_t)((i_idx + k_idx) % 100) / (num_t)m_len_a;
			else
				A[state] = (num_t)-999;
		});
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_symm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// C: i x j
	// A: i x k (square M x M)
	// B: i x j
	// Form C := alpha*A*B + beta*C, symmetric A (lower stored)

	#pragma scop
	traverser(C, B).template for_dims<'i'>([=](auto trav_i) {
		auto state_i = trav_i.state();
		auto i_idx = get_index<'i'>(state_i);

		trav_i.template for_dims<'j'>([=](auto trav_ij) {
			auto state_ij = trav_ij.state();
			auto j_idx = get_index<'j'>(state_ij);

			num_t temp2 = (num_t)0;

			// B[i][j]
			num_t Bij = B[state_ij];

			// Views for the inner k-loop
			// A_i: row i, indexed by k (A[i][k])
			auto A_i = A ^ fix<'i'>(i_idx); // dims: 'k'

			// Column j of C and B: dims 'i', rename 'i' -> 'k' to align with A_i
			auto C_col   = C ^ fix<'j'>(j_idx);          // dims: 'i'
			auto B_col   = B ^ fix<'j'>(j_idx);          // dims: 'i'
			auto C_col_k = C_col ^ rename<'i', 'k'>();   // dims: 'k'
			auto B_col_k = B_col ^ rename<'i', 'k'>();   // dims: 'k'

			// Inner loop over k < i
			traverser(A_i, B_col_k, C_col_k).template for_each<'k'>([&](auto state_k) {
				auto k_idx = get_index<'k'>(state_k);

				if (k_idx < i_idx) {
					// C[k][j] += alpha * B[i][j] * A[i][k]
					C_col_k[state_k] += alpha * Bij * A_i[state_k];
					// temp2 += B[k][j] * A[i][k]
					temp2 += B_col_k[state_k] * A_i[state_k];
				}
			});

			// Diagonal term A[i][i]
			num_t Aii = A_i.template at<'k'>(i_idx);
			num_t Cij = C[state_ij];

			C[state_ij] = beta * Cij + alpha * Bij * Aii + alpha * temp2;
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// input data
	num_t alpha;
	num_t beta;

	// set lengths for all relevant dimensions
	auto set_lengths =
		noarr::set_length<'i'>(m) ^
		noarr::set_length<'j'>(n) ^
		noarr::set_length<'k'>(m);

	// allocate bags
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths);
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize data
	init_array(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_symm(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, C.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}

